"""Count PTX instruction kinds in the kernels of built benchmarks."""

import argparse
import re
import subprocess
from pathlib import Path

MLIR_OPT = "/home/jhale/llvm-mlir-22.1.2/install/bin/mlir-opt"
LOWERING = [
    "-convert-linalg-to-loops",
    "-fold-memref-alias-ops",
    "-expand-strided-metadata",
    "-lower-affine",
    "-convert-scf-to-cf",
    "-gpu-lower-to-nvvm-pipeline=cubin-chip=sm_70 cubin-format=isa opt-level=3",
]
KINDS = {
    "bar.sync": r"\bbar\.sync",
    "ld.shared": r"\bld\.shared",
    "st.shared": r"\bst\.shared",
    "ld.global": r"\bld\.global",
    "st.global": r"\bst\.global",
    "local": r"\.local",
    "fma.f64": r"\bfma\.rn\.f64",
}


def ptx(gpu_mlir: Path) -> list[str]:
    """The PTX of each GPU module, which holds one kernel."""
    lowered = subprocess.run(
        [MLIR_OPT, gpu_mlir, *LOWERING], check=True, capture_output=True, text=True
    ).stdout
    # MLIR escapes the PTX text of a gpu.binary, for example newlines as \0A.
    texts = re.findall(r'"(//\\0A// Generated by LLVM NVPTX.*?)"', lowered, re.S)
    return [re.sub(r"\\([0-9A-Fa-f]{2})", lambda m: chr(int(m.group(1), 16)), t) for t in texts]


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("gpu_mlir", type=Path, nargs="+", help="*.gpu.mlir files")
    args = parser.parse_args()
    print(f"{'kernel':45s} " + " ".join(f"{k:>9s}" for k in KINDS))
    for path in args.gpu_mlir:
        for text in ptx(path):
            (kernel,) = re.findall(r"\.entry (\w+)", text)
            lines = text.splitlines()
            counts = [sum(1 for line in lines if re.search(p, line)) for p in KINDS.values()]
            name = path.name.removesuffix(".gpu.mlir")
            print(f"{name + ' ' + kernel:45s} " + " ".join(f"{c:9d}" for c in counts))


if __name__ == "__main__":
    main()
